### Iteration 2: Shared Memory Optimization
We'll implement a tiled matrix multiplication using shared memory. This reduces global memory accesses by loading blocks of matrices into shared memory.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int tRow = threadIdx.y;
        int tCol = threadIdx.x;
        int A_col = t * TILE_SIZE + tCol;

        if (row < M && A_col < K) {
            As[tRow][tCol] = A[row * K + A_col];
        } else {
            As[tRow][tCol] = 0.0f;
        }

        // Load tile of B into shared memory
        int B_row = t * TILE_SIZE + tRow;
        if (B_row < K && col < N) {
            Bs[tRow][tCol] = B[B_row * N + col];
        } else {
            Bs[tRow][tCol] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[tRow][k] * Bs[k][tCol];
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

