### Iteration 3: Register Blocking and Loop Unrolling
We'll implement a more advanced optimization where each thread computes a 4x4 block of the output matrix. This reduces global memory accesses and increases arithmetic intensity. We'll also unroll the inner loop to reduce instruction overhead.

```python
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define BLOCK_SIZE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y * BLOCK_SIZE;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x * BLOCK_SIZE;

    float c[BLOCK_SIZE][BLOCK_SIZE] = {{0.0f}};

    for (int t = 0; t < (K + TILE_SIZE - 1) / TILE_SIZE; t++) {
        // Load tile of A into shared memory
        int tRow = threadIdx.y * BLOCK_SIZE;
        int tCol = threadIdx.x;
        for (int i = 0; i < BLOCK_SIZE; i++) {
            int A_row = row + i;
            int A_col = t * TILE_SIZE + tCol;
            if (A_row < M && A_col < K) {
                As[tRow + i][tCol] = A[A_row * K + A_col];
            } else {
                As[tRow + i][tCol] = 0.0f;
            }
        }

        // Load tile of B into shared memory
        int B_row = t * TILE_SIZE + threadIdx.y * BLOCK_SIZE;
        for (int i = 0; i < BLOCK_SIZE; i++) {
            int B_col = col + i;
            if (B_row + i < K && B_col < N) {
                Bs[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE] = B[(B_row + i) * N + B_col];
            } else {
                Bs[threadIdx.y * BLOCK_SIZE + i][threadIdx.x * BLOCK_SIZE] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial product with loop unrolling
        for (int k = 0; k < TILE_SIZE; k++) {
            #pragma unroll
            for (int i = 0; i < BLOCK_SIZE; i++) {
                #pragma unroll
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    c[i][j] += As[threadIdx.y * BLOCK_SIZE + i][k] * Bs[k][threadIdx.x * BLOCK_SIZE + j];
                }
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    for (int i = 0; i < BLOCK_SIZE; i++) {
        for (int j = 0; j < BLOCK_SIZE; j++) {
            if (row + i < M && col + j < N) {
                C[(row + i) * N + (col + j)] = c[i][j];
            }
        }
    }
}

